css:
.print-format { font-family: Tahoma, Arial, sans-serif; color: #333333; }
.print-format .print-heading { border-bottom: 2px solid #00844E; margin-bottom: 14px; }
.print-format .print-heading h2 { color: #072B1A; font-weight: bold; }
.print-format .print-heading .sub-heading { color: #00844E; }
.print-format .section-break h4 { color: #072B1A; border-bottom: 1px solid #ECE6D6; padding-bottom: 4px; }
.print-format .section-break label { color: #072B1A; }
.print-format .section-break table { border-bottom: 2px solid #00844E; }
.print-format .section-break table th { background-color: #072B1A !important; color: #ffffff !important; border-color: #072B1A !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.print-format .section-break table td { border-color: #e5e5e5 !important; }
.print-format .section-break table tr:nth-child(even) td { background-color: #f7f7f7; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
